using System;
using System.IO;
using UnityEngine;

namespace EyeCamXR.Tests
{
    /// <summary>
    /// Golden vectors generated by C:\Users\alexa\eyecam\gen_golden.py.
    /// All doubles travel as base64 little-endian float64 (bit-exact, NaN-safe;
    /// JsonUtility numeric parsing does not guarantee last-ulp round-trips).
    /// </summary>
    public static class Golden
    {
        public static string Dir =>
            Path.Combine(Application.dataPath, "EyeCamXR", "Tests", "Golden");

        public static T Load<T>(string file) =>
            JsonUtility.FromJson<T>(File.ReadAllText(Path.Combine(Dir, file)));

        public static double[] Doubles(string b64)
        {
            var bytes = Convert.FromBase64String(b64);
            var result = new double[bytes.Length / 8];
            Buffer.BlockCopy(bytes, 0, result, 0, bytes.Length);
            return result;
        }

        public static double Scalar(string b64) => Doubles(b64)[0];

        /// <summary>chFlat is channel-major: [ch0 samples..., ch1 samples...].</summary>
        public static double[][] Channels(string chFlatB64, int nCh)
        {
            var flat = Doubles(chFlatB64);
            int n = flat.Length / nCh;
            var chans = new double[nCh][];
            for (int c = 0; c < nCh; c++)
            {
                chans[c] = new double[n];
                Array.Copy(flat, c * n, chans[c], 0, n);
            }
            return chans;
        }

        public static void AssertClose(double actual, double expected,
                                       double relTol, string label)
        {
            if (double.IsNaN(expected))
            {
                NUnit.Framework.Assert.IsTrue(double.IsNaN(actual),
                    $"{label}: expected NaN, got {actual}");
                return;
            }
            NUnit.Framework.Assert.IsFalse(double.IsNaN(actual),
                $"{label}: got NaN, expected {expected}");
            double tol = relTol * Math.Max(Math.Abs(expected), 1e-30);
            NUnit.Framework.Assert.LessOrEqual(Math.Abs(actual - expected), tol,
                $"{label}: {actual} vs {expected} (tol {tol})");
        }
    }

